/* TokenTrust — "final" ASCII lockup, embedded build of tokentrust_final.html.
   Mounts into <canvas id="tt-ascii">. Fixed 4:3 internal buffer fills the 4:3
   card via CSS. No web font / external SVG (the lockup + logos are inline).
   Pauses when the card is off-screen or the tab is hidden; ~30fps. */
(() => {
  "use strict";

  /* ------------------------------------------------------------------
     TokenTrust — mono edition (white).
     A procedural dither field shifts between glyph "biomes": clover,
     geometric, dots, line/zigzag, Bayer halftone blocks, and a logo
     biome of simplified AI-brand motifs (4-point spark, sunburst,
     blossom, slash). Motifs are drawn from embedded geometry, so no
     external SVG is needed. The horizontal TokenTrust lockup is mounted
     (recolored white) in a rounded box. Monochrome white on near-black.
  -------------------------------------------------------------------*/

  const BG       = "#1a1a1a";
  const WHITE    = [238, 238, 235];
  const LOGO_OP  = 0.78;   // logos kept translucent
  const GRAY_HI  = [200, 200, 196];
  const GRAY     = [120, 120, 118];
  const BOX_BG   = "#141413";
  const BOX_LINE = "rgba(255,255,255,0.22)";

  const STAR_PATH = "M232.841 10.5296L182.681 131.282L304.054 81.1211L315.82 107.134L193.829 157.288L315.82 207.449L304.054 232.841L182.681 182.68L232.841 304.054L207.452 315.82L157.292 193.824L107.131 315.82L81.7422 304.054L131.284 182.68L10.5297 232.841L0 207.449L120.754 157.288L0 107.134L10.5297 81.743L131.284 131.282L81.7422 10.5296L107.131 0L157.292 120.752L207.452 0L232.841 10.5296Z";
  const STAR_VIEW = 315.82, STAR_CENTER = STAR_VIEW / 2;
  const starPath = new Path2D(STAR_PATH);

  // glyph biomes
  const B_CLOVER = ["\u00b7","\u2667","\u2663","\u273f","\u2740"];
  const B_GEO    = ["\u00b7","\u25c7","\u25c6","\u25a3","\u25a0"];
  const B_DOTS   = ["\u00b7","\u2022","\u25e6","\u25cb","\u25c9","\u25cf"];
  const B_LINE   = ["\u2502","\u2571","\u2572","\u2573","\u2550"];
  const B_BLOCK  = [" ","\u2591","\u2592","\u2593","\u2588"];
  const BAYER = [[0,8,2,10],[12,4,14,6],[3,11,1,9],[15,7,13,5]];

  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const ROT_SPEED = reduceMotion ? 0.05 : 0.14;

  const stage = document.getElementById("tt-ascii");
  if (!stage) return;   // only on the page that has the card
  const ctx = stage.getContext("2d");
  const scene = document.createElement("canvas");
  const sctx = scene.getContext("2d");
  const bloom = document.createElement("canvas");
  const blctx = bloom.getContext("2d");
  const SB = 360;
  const shape = document.createElement("canvas");
  shape.width = SB; shape.height = SB;
  const shctx = shape.getContext("2d", { willReadFrequently: true });

  function hash(x,y){ let n=Math.sin(x*127.1+y*311.7)*43758.5453; return n-Math.floor(n); }
  const smooth = t => t*t*(3-2*t);
  const lerp = (a,b,t) => a+(b-a)*t;
  function vnoise(x,y){
    const xi=Math.floor(x),yi=Math.floor(y),xf=x-xi,yf=y-yi,u=smooth(xf),v=smooth(yf);
    const a=hash(xi,yi),b=hash(xi+1,yi),c=hash(xi,yi+1),d=hash(xi+1,yi+1);
    return lerp(lerp(a,b,u),lerp(c,d,u),v);
  }
  function fbm(x,y){ let val=0,amp=0.5,f=1; for(let i=0;i<4;i++){val+=amp*vnoise(x*f,y*f);f*=2;amp*=0.5;} return val; }

  const W=1440, H=1080, U=Math.min(W,H);
  let cell=28, cols=0, rows=0, monoMain="";
  const GF=0.014, MAC=0.0026, MESO=0.0078, RG=0.0034, BF=0.0040;

  function setup(){
    cell = Math.max(24, Math.min(52, Math.round(U/27)));
    cols = Math.ceil(W/cell)+1; rows = Math.ceil(H/cell)+1;
    for(const c of [stage,scene,bloom]){ c.width=W; c.height=H; }
    monoMain = `${Math.round(cell*0.92)}px ui-monospace,"SF Mono",Menlo,Consolas,monospace`;
    sctx.textAlign="center"; sctx.textBaseline="middle";
  }
  // CSS sizes the canvas (width/height:100%); the fixed 4:3 buffer just
  // scales to the 4:3 card — no window-based fitting needed.
  setup();

  function rgba(c,a){ return `rgba(${c[0]},${c[1]},${c[2]},${a.toFixed(3)})`; }

  // ---- embedded brand-logo icons (extracted from the actual SVGs, recolored white) ----
  const LOGO_B64 = {
    gemini: "",
    claude: "",
    openai: "",
    grok:   ""
  };
  const LOGOS = ["gemini","claude","openai","grok"].map(k => {
    const im = new Image(); im._ready = false; im.onload = () => { im._ready = true; };
    im.src = "data:image/svg+xml;base64," + LOGO_B64[k];
    return im;
  });

  // ---- mount the horizontal lockup, recolored white ----
  const SVG_RAW = `<svg width="508" height="85" viewBox="0 0 508 85" fill="none" xmlns="http://www.w3.org/2000/svg">
<mask id="mask0_5_20" style="mask-type:luminance" maskUnits="userSpaceOnUse" x="0" y="0" width="85" height="85">
<path d="M84.2188 0H0V84.2188H84.2188V0Z" fill="white"/>
</mask>
<g mask="url(#mask0_5_20)">
<path fill-rule="evenodd" clip-rule="evenodd" d="M62.0909 2.8079L48.7149 35.0085L81.0809 21.6323L84.2187 28.5692L51.6878 41.9435L84.2187 55.3198L81.0809 62.0908L48.7149 48.7146L62.0909 81.0811L55.3205 84.2188L41.9444 51.6865L28.5684 84.2188L21.7979 81.0811L35.009 48.7146L2.80793 62.0908L0 55.3198L32.201 41.9435L0 28.5692L2.80793 21.7981L35.009 35.0085L21.7979 2.8079L28.5684 0L41.9444 32.2006L55.3205 0L62.0909 2.8079Z" fill="black"/>
</g>
<path d="M124.769 82.8034V27.1863H103.419V19.5422H155.433V27.1863H134.083V82.8034H124.769Z" fill="black"/>
<path d="M170.098 83.682C165.529 83.682 161.516 82.6862 158.06 80.6947C154.605 78.6445 151.91 75.8622 149.977 72.3477C148.044 68.7746 147.078 64.7329 147.078 60.2226C147.078 55.6538 148.044 51.6414 149.977 48.1855C151.969 44.7295 154.663 42.0351 158.06 40.1021C161.516 38.1105 165.529 37.1147 170.098 37.1147C174.725 37.1147 178.767 38.1105 182.223 40.1021C185.679 42.0351 188.344 44.7295 190.218 48.1855C192.151 51.6414 193.118 55.6538 193.118 60.2226C193.118 64.7329 192.151 68.7746 190.218 72.3477C188.344 75.8622 185.679 78.6445 182.223 80.6947C178.767 82.6862 174.725 83.682 170.098 83.682ZM170.098 76.2137C172.851 76.2137 175.223 75.54 177.215 74.1928C179.265 72.8456 180.875 70.9712 182.047 68.5696C183.218 66.168 183.804 63.3564 183.804 60.1348C183.804 55.3316 182.516 51.5535 179.938 48.8005C177.42 45.9889 174.139 44.5831 170.098 44.5831C166.115 44.5831 162.834 45.9889 160.257 48.8005C157.738 51.6121 156.479 55.3902 156.479 60.1348C156.479 63.3564 157.035 66.168 158.148 68.5696C159.32 70.9712 160.931 72.8456 162.981 74.1928C165.089 75.54 167.462 76.2137 170.098 76.2137Z" fill="black"/>
<path d="M198.11 82.8034V18.4H207.248V82.8034H198.11ZM227.193 82.8034L205.139 59.5197L226.49 37.9934H238L213.75 61.5406L214.189 57.411L238.878 82.8034H227.193Z" fill="black"/>
<path d="M258.179 83.682C253.669 83.682 249.686 82.6862 246.23 80.6947C242.833 78.7031 240.167 75.9501 238.234 72.4356C236.302 68.9211 235.335 64.8794 235.335 60.3105C235.335 55.6831 236.272 51.6414 238.147 48.1855C240.08 44.6709 242.774 41.9472 246.23 40.0142C249.686 38.0812 253.64 37.1147 258.091 37.1147C262.426 37.1147 266.175 38.052 269.338 39.9264C272.56 41.7422 275.02 44.2902 276.718 47.5704C278.476 50.8506 279.354 54.7459 279.354 59.2562C279.354 59.9591 279.325 60.6327 279.266 61.277C279.266 61.8627 279.208 62.4778 279.091 63.1221H241.485V56.2688H272.677L270.392 58.9926C270.392 54.1894 269.309 50.5285 267.141 48.0097C264.974 45.491 261.957 44.2316 258.091 44.2316C253.933 44.2316 250.623 45.6667 248.163 48.5369C245.761 51.3485 244.561 55.273 244.561 60.3105C244.561 65.4065 245.761 69.3897 248.163 72.2598C250.623 75.13 254.02 76.5651 258.355 76.5651C260.991 76.5651 263.275 76.0379 265.208 74.9836C267.141 73.8707 268.576 72.2598 269.514 70.1511H278.124C276.66 74.3685 274.17 77.678 270.656 80.0796C267.2 82.4812 263.041 83.682 258.179 83.682Z" fill="black"/>
<path d="M284.308 82.8034V37.9934H293.007V48.5369H293.446V82.8034H284.308ZM316.114 82.8034V53.9844C316.114 50.8799 315.324 48.5662 313.742 47.0432C312.219 45.5203 309.935 44.7588 306.889 44.7588C304.253 44.7588 301.91 45.3446 299.86 46.5161C297.868 47.6876 296.287 49.2984 295.115 51.3485C294.002 53.3986 293.446 55.8295 293.446 58.6411L292.304 47.9219C293.768 44.5831 296.023 41.9472 299.069 40.0142C302.115 38.0812 305.659 37.1147 309.701 37.1147C314.504 37.1147 318.282 38.462 321.035 41.1564C323.788 43.8509 325.164 47.424 325.164 51.8757V82.8034H316.114Z" fill="black"/>
<path d="M341.509 82.8034V27.1863H320.158V19.5422H372.173V27.1863H350.822V82.8034H341.509Z" fill="black"/>
<path d="M367.074 82.8034V37.9934H375.773V49.1519H376.212V82.8034H367.074ZM376.212 59.4319L375.07 48.8005C376.124 44.9931 377.94 42.0936 380.517 40.1021C383.094 38.1105 386.17 37.1147 389.743 37.1147C391.09 37.1147 392.027 37.2319 392.554 37.4662V46.0767C392.261 45.9596 391.851 45.901 391.324 45.901C390.797 45.8424 390.153 45.8132 389.391 45.8132C384.998 45.8132 381.689 46.9554 379.463 49.2398C377.296 51.5242 376.212 54.9216 376.212 59.4319Z" fill="black"/>
<path d="M410.301 83.682C407.313 83.682 404.677 83.0669 402.393 81.8369C400.108 80.5482 398.322 78.791 397.033 76.5651C395.803 74.3392 395.188 71.7912 395.188 68.9211V37.9934H404.326V66.8123C404.326 69.9168 405.087 72.2305 406.61 73.7535C408.133 75.2765 410.301 76.0379 413.112 76.0379C415.631 76.0379 417.857 75.4522 419.79 74.2807C421.781 73.1092 423.334 71.4984 424.446 69.4482C425.618 67.3395 426.204 64.9087 426.204 62.1556L427.346 72.8749C425.882 76.1551 423.626 78.791 420.581 80.7825C417.593 82.7155 414.167 83.682 410.301 83.682ZM426.555 82.8034V72.2598H426.204V37.9934H435.254V82.8034H426.555Z" fill="black"/>
<path d="M459.486 83.682C453.628 83.682 448.972 82.3933 445.516 79.816C442.06 77.2387 440.097 73.6071 439.629 68.9211H448.064C448.474 71.4984 449.645 73.4899 451.578 74.8957C453.57 76.2429 456.264 76.9166 459.662 76.9166C462.649 76.9166 464.933 76.3894 466.515 75.335C468.096 74.2807 468.887 72.787 468.887 70.854C468.887 69.4482 468.419 68.2767 467.481 67.3395C466.603 66.3437 464.845 65.5237 462.21 64.8794L455.005 63.21C450.495 62.097 447.126 60.4569 444.901 58.2897C442.733 56.0638 441.65 53.3401 441.65 50.1184C441.65 46.0767 443.143 42.9137 446.131 40.6293C449.177 38.2863 453.335 37.1147 458.607 37.1147C463.82 37.1147 468.009 38.2863 471.172 40.6293C474.393 42.9723 476.209 46.2525 476.619 50.4699H468.184C467.833 48.3612 466.808 46.7504 465.109 45.6374C463.469 44.4659 461.214 43.8802 458.344 43.8802C455.649 43.8802 453.57 44.3781 452.105 45.3738C450.7 46.311 449.997 47.629 449.997 49.3277C449.997 50.7335 450.524 51.905 451.578 52.8422C452.691 53.7794 454.507 54.5701 457.026 55.2145L464.406 57.0596C468.682 58.1139 471.904 59.8419 474.071 62.2435C476.238 64.5865 477.322 67.4274 477.322 70.7662C477.322 74.8079 475.74 77.9709 472.577 80.2553C469.473 82.5398 465.109 83.682 459.486 83.682Z" fill="black"/>
<path d="M500.379 83.682C495.166 83.682 491.329 82.4812 488.869 80.0796C486.467 77.6195 485.267 74.0171 485.267 69.2725V27.7134L494.317 24.2868V69.3604C494.317 71.7034 494.932 73.4313 496.162 74.5443C497.392 75.6572 499.383 76.2137 502.136 76.2137C503.191 76.2137 504.128 76.1258 504.948 75.9501C505.768 75.7743 506.471 75.5693 507.057 75.335V82.7155C506.412 83.0084 505.504 83.2427 504.333 83.4184C503.161 83.5941 501.843 83.682 500.379 83.682ZM476.305 45.286V37.9934H507.057V45.286H476.305Z" fill="black"/>
<path d="M486.986 14.208C485.373 14.208 484.087 13.8112 483.127 13.0176C482.18 12.224 481.623 11.0912 481.457 9.6192H482.993C483.133 10.6816 483.537 11.4816 484.202 12.0192C484.868 12.5568 485.789 12.8256 486.967 12.8256C487.965 12.8256 488.714 12.64 489.213 12.2688C489.725 11.8848 489.981 11.328 489.981 10.5984C489.981 9.9712 489.809 9.472 489.463 9.1008C489.117 8.7296 488.58 8.4224 487.85 8.1792L485.527 7.3728C484.349 6.9632 483.479 6.4704 482.916 5.8944C482.353 5.3056 482.071 4.5632 482.071 3.6672C482.071 2.9248 482.257 2.2848 482.628 1.7472C482.999 1.1968 483.524 0.768 484.202 0.4608C484.881 0.1536 485.668 0 486.564 0C487.946 0 489.053 0.3648 489.885 1.0944C490.717 1.8112 491.197 2.8352 491.325 4.1664H489.789C489.623 3.2064 489.277 2.5024 488.753 2.0544C488.241 1.6064 487.498 1.3824 486.525 1.3824C485.604 1.3824 484.887 1.568 484.375 1.9392C483.863 2.3104 483.607 2.8352 483.607 3.5136C483.607 4.0896 483.786 4.5504 484.145 4.896C484.503 5.2416 485.06 5.5424 485.815 5.7984L488.292 6.6624C489.367 7.0336 490.173 7.5392 490.711 8.1792C491.249 8.8064 491.517 9.6064 491.517 10.5792C491.517 11.7312 491.121 12.6272 490.327 13.2672C489.546 13.8944 488.433 14.208 486.986 14.208Z" fill="black"/>
<path d="M493.023 14.0352V0.2112H495.442L500.434 13.536H499.704L504.658 0.2112H507.115V14.0352H505.56V1.0368H505.771L500.952 14.0352H499.071L494.251 1.152H494.463V14.0352H493.023Z" fill="black"/>
</svg>`;
  const svgColored = SVG_RAW.replace(/fill="black"/g, 'fill="#F0F0EE"');
  const lockImg = new Image();
  let lockReady = false;
  lockImg.onload = () => { lockReady = true; };
  lockImg.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svgColored);
  const LOCK_AR = 85/508;

  let angle=0, last=performance.now(), lastDraw=0, rafId=null, inView=true;
  const FRAME_MS=1000/30;   // ~30fps throttle

  function frame(now){
    rafId=requestAnimationFrame(frame);
    if(now-lastDraw<FRAME_MS) return;            // throttle to ~30fps
    const dt=Math.min(0.05,(now-last)/1000); last=now; lastDraw=now;
    angle += dt*ROT_SPEED;
    const t = now/1000;

    shctx.clearRect(0,0,SB,SB);
    shctx.save();
    shctx.filter="blur(2px)";
    shctx.translate(SB/2,SB/2); shctx.rotate(angle);
    const ss=(SB*0.92)/STAR_VIEW; shctx.scale(ss,ss);
    shctx.translate(-STAR_CENTER,-STAR_CENTER);
    shctx.fillStyle="#fff"; shctx.fill(starPath);
    shctx.restore();
    const sd=shctx.getImageData(0,0,SB,SB).data;

    const mcx=W/2, mcy=H*0.46, mSize=U*0.92, half=mSize/2;

    sctx.clearRect(0,0,W,H);
    sctx.font=monoMain;

    for(let gy=0; gy<rows; gy++){
      const py=gy*cell+cell/2, ry=(py-mcy)/half;
      for(let gx=0; gx<cols; gx++){
        const px=gx*cell+cell/2, rx=(px-mcx)/half;

        let body=0;
        const sx=(rx*0.5+0.5)*SB, sy=(ry*0.5+0.5)*SB;
        if(sx>=0&&sx<SB&&sy>=0&&sy<SB) body=sd[((sy|0)*SB+(sx|0))*4]/255;

        // ---- B + A : logos form the rotating mark, with sparse logos scattered in the void ----
        const fine  = fbm(px*0.022+t*0.10, py*0.022-t*0.08);
        const macro = fbm(px*0.0045+3.0,  py*0.0045-2.0);
        const starV = body*(0.58+0.42*fine);                 // the mark, built from logos
        const scatterRaw = macro*0.62 + fine*0.38;
        let v = starV;
        if(body<0.06 && scatterRaw>0.62) v = 0.28 + (scatterRaw-0.62)*1.1;  // sparse outer scatter
        if(v<0.24) continue;                                  // generous negative space
        if(v>1) v=1;

        // every unit is a real brand-logo SVG; clustered by region noise + light mixing
        const rnoise = fbm(px*0.0034+5.0, py*0.0034-9.0);
        const jit = vnoise(gx*1.9+2.0, gy*2.7-1.0);
        let idx = (Math.min(0.999, Math.max(0, rnoise))*4)|0;
        if(jit>0.82) idx=(idx+1)&3;
        const im = LOGOS[idx];
        if(im._ready){
          const sz = Math.min(cell*0.92, cell*(0.46+0.56*v));   // <= cell -> never overlaps
          if(sz>=3){
            sctx.globalAlpha = Math.min(1, (0.42+0.55*v)*LOGO_OP);   // translucent logos
            sctx.drawImage(im, px-sz/2, py-sz/2, sz, sz);
            sctx.globalAlpha = 1;
          }
        }
      }
    }

    ctx.clearRect(0,0,W,H);
    ctx.fillStyle=BG; ctx.fillRect(0,0,W,H);
    ctx.drawImage(scene,0,0);
    // glow: two-pass additive halo from the transparent logo layer (blacks stay black)
    ctx.globalCompositeOperation="lighter";
    blctx.clearRect(0,0,W,H);
    blctx.filter=`blur(${(U*0.006).toFixed(1)}px)`; blctx.drawImage(scene,0,0); blctx.filter="none";
    ctx.globalAlpha=0.42; ctx.drawImage(bloom,0,0);
    blctx.clearRect(0,0,W,H);
    blctx.filter=`blur(${(U*0.016).toFixed(1)}px)`; blctx.drawImage(scene,0,0); blctx.filter="none";
    ctx.globalAlpha=0.24; ctx.drawImage(bloom,0,0);
    ctx.globalAlpha=1; ctx.globalCompositeOperation="source-over";

    drawLockup();
  }

  function drawLockup(){
    const lw = Math.round(W*0.50);
    const lh = Math.round(lw*LOCK_AR);
    const padX = Math.round(lh*0.70), padY = Math.round(lh*0.62);
    const boxW = lw + padX*2;
    const boxH = lh + padY*2;
    const bx = Math.round(W/2 - boxW/2);
    const by = Math.round(H*0.46 - boxH/2);
    // box color == background -> the lockup knocks a clean pocket out of the pattern
    ctx.fillStyle=BG;
    ctx.fillRect(bx,by,boxW,boxH);

    const lx = bx+padX, ly = by+padY;
    if(lockReady) ctx.drawImage(lockImg, lx, ly, lw, lh);
    // swap the lockup's static mark for a rotating one
    ctx.fillStyle=BG;
    ctx.fillRect(lx, ly, lh, lh);
    drawStar(ctx, lx+lh/2, ly+lh/2, lh*0.96, angle, "#F0F0EE");
  }

  function drawStar(g,cx,cy,size,rot,color){
    g.save(); g.translate(cx,cy); g.rotate(rot);
    const s=size/STAR_VIEW; g.scale(s,s); g.translate(-STAR_CENTER,-STAR_CENTER);
    g.fillStyle=color; g.fill(starPath); g.restore();
  }

  function roundRect(g,x,y,w,h,r){
    g.beginPath(); g.moveTo(x+r,y);
    g.arcTo(x+w,y,x+w,y+h,r); g.arcTo(x+w,y+h,x,y+h,r);
    g.arcTo(x,y+h,x,y,r); g.arcTo(x,y,x+w,y,r); g.closePath();
  }

  function start(){ if(rafId==null){ last=performance.now(); rafId=requestAnimationFrame(frame); } }
  function stop(){ if(rafId!=null){ cancelAnimationFrame(rafId); rafId=null; } }
  function apply(){ if(inView && !document.hidden) start(); else stop(); }
  if("IntersectionObserver" in window){
    new IntersectionObserver(es=>{ inView=es[0].isIntersecting; apply(); },{threshold:0}).observe(stage);
  }
  document.addEventListener("visibilitychange", apply);
  start();

})();
